"""First administrator, created on first boot from the password generated by the init service."""

import logging

from sqlalchemy import select
from sqlalchemy.orm import Session

from app.core.context import AppContext
from app.models import User
from app.services import audit_service
from app.services.audit_service import SYSTEM
from app.services.user_profile import new_user

logger = logging.getLogger(__name__)

BOOTSTRAP_USERNAME = "admin"
BOOTSTRAP_PASSWORD_SECRET = "app/bootstrap_admin_password"  # noqa: S105  # nosec B105


def ensure_bootstrap_admin(db: Session, ctx: AppContext, password: str) -> bool:
    """Create the bootstrap admin when no administrator exists. Returns True if created."""
    if db.scalar(select(User.id).where(User.global_role == "admin").limit(1)) is not None:
        return False
    user = new_user(ctx.cipher, BOOTSTRAP_USERNAME, role="admin")
    user.password_hash = ctx.hasher.hash(password)
    user.must_change_password = True
    db.add(user)
    db.flush()
    audit_service.record(
        db, SYSTEM, "user.bootstrap_admin_created", target_type="user", target_id=user.id
    )
    db.commit()
    logger.info("Bootstrap administrator created", extra={"username": BOOTSTRAP_USERNAME})
    return True


def bootstrap_password_still_valid(db: Session) -> bool:
    """The generated password is shown only while the bootstrap admin has not replaced it."""
    user = db.scalar(select(User).where(User.username == BOOTSTRAP_USERNAME))
    return user is not None and user.must_change_password and user.password_changed_at is None
